head.script:
var ganttChart = null;


/**
 * DHTMLX Gantt CSS 동적 로딩
 */
function loadDhtmlxCSS() {
    return new Promise(function (resolve, reject) {
        var link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = 'https://cdn.dhtmlx.com/gantt/edge/dhtmlxgantt.css';
        link.onload = function () {
            console.log("DHTMLX Gantt CSS 로딩 완료");
            resolve();
        };
        link.onerror = function () {
            console.error("DHTMLX Gantt CSS 로딩 실패");
            reject();
        };
        document.head.appendChild(link);
    });
}

/**
 * DHTMLX Gantt 라이브러리 로딩 확인
 */
function waitForDhtmlxGantt(callback) {
    if (typeof gantt !== 'undefined') {
        callback();
    } else {
        setTimeout(function () {
            waitForDhtmlxGantt(callback);
        }, 100);
    }
}

scwin.onpageload = function () {
    let pjtId = $p.parent().scwin.SEL_PJT_ID;
    console.log("선택되 프로젝트 ID : " , pjtId);
    dmp_searchVo.set("pjtId", pjtId);

    console.log("DHTMLX Gantt 간트차트 페이지 로딩 시작");



    // 1단계: CSS 동적 로딩
    loadDhtmlxCSS().then(function () {
        console.log("CSS 로딩 성공, Gantt 라이브러리 확인 중...");

        // 2단계: Gantt 라이브러리 확인
        waitForDhtmlxGantt(function () {
            console.log("DHTMLX Gantt 라이브러리 로딩 완료");

            // 3단계: 간트차트 초기화 후 데이터 로딩
            setTimeout(function () {
                scwin.initGanttConfig();
                scwin.loadTaskList();
            }, 300);
        });
    }).catch(function () {
        console.error("CSS 로딩 실패");
        scwin.showErrorState("CSS 로딩에 실패했습니다.");
    });
};

/**
 * DHTMLX Gantt 설정 초기화 - 계획을 상위로 하는 트리 구조
 */
scwin.initGanttConfig = function () {
    try {
        // 기본 설정
        gantt.config.date_format = "%Y-%m-%d";
        gantt.config.xml_date = "%Y-%m-%d";
        gantt.config.duration_unit = "day";

        // 스크롤 및 크기 설정
        gantt.config.autosize = false;
        gantt.config.autofit = false;
        gantt.config.scroll_on_load = true;
        gantt.config.fit_tasks = false;

        // 마우스 휠 및 스크롤 설정 개선
        gantt.config.wheel_scroll_sensitivity = 1;
        gantt.config.horizontal_scroll_key = "shiftKey"; // Shift + 휠로 가로 스크롤
        gantt.config.scroll_speed = 30;


        // 추가 스크롤 설정
        gantt.config.smart_rendering = true;
        gantt.config.static_background = true;

        // 행 높이 설정 (축소)
        gantt.config.row_height = 35; // 40 → 35로 축소
        gantt.config.scale_height = 50;
        gantt.config.task_height = 20;

        // 기본 스케일 설정 (월별)
        gantt.config.scales = [
            { unit: "month", step: 1, format: "%Y년 %m월" },
            { unit: "day", step: 1, format: "%d" }
        ];

        gantt.config.min_column_width = 30;

        // 툴팁 활성화 및 현재 날짜 라인 추가
        gantt.plugins({
            tooltip: true,
            marker: true, // 현재 날짜 마커 플러그인 활성화
            click_drag: true,
            drag_timeline: true,
        });



        // 기타 설정
        gantt.config.sort = true;
        gantt.config.open_tree_initially = true;

        // 컬럼 설정
        gantt.config.columns = [
            { name: "text", label: "업무명", width: 200, tree: true },
            { name: "stage", label: "단계", width: 70, align: "center" },
            {
                name: "status", label: "상태", width: 70, align: "center", template: function (task) {
                    if (!task.task_type) return "";
                    return '<span class="status_badge ' + scwin.getStatusClass(task.status) + '">' + (task.status || '대기') + '</span>';
                }
            },
            { name: "assignee", label: "담당자", width: 80, align: "center" },
            {
                name: "progress", label: "진척률", width: 70, align: "center", template: function (task) {
                    if (!task.task_type) return "";
                    return Math.round(task.progress * 100) + "%";
                }
            }
        ];

        // 작업 바 스타일 템플릿 (계획/실제 구분 + 진척률 투명도)
        gantt.templates.task_class = function (start, end, task) {
            var classes = [];

            // 작업 타입별 클래스
            if (task.task_type === "planned") {
                classes.push("planned_task");
            } else if (task.task_type === "actual") {
                classes.push("actual_task");
            }

            // 상태별 클래스
            var status = task.status || "waiting";
            classes.push("status_" + status.replace(/\s+/g, "_"));

            // 진척률에 따른 투명도 클래스
            var progress = Math.round(task.progress * 100);
            if (progress === 0) classes.push("progress_0");
            else if (progress <= 25) classes.push("progress_25");
            else if (progress <= 50) classes.push("progress_50");
            else if (progress <= 75) classes.push("progress_75");
            else classes.push("progress_100");

            return classes.join(" ");
        };

        // 작업 바 텍스트 템플릿 (텍스트 제거)
        gantt.templates.task_text = function (start, end, task) {
            return ""; // 모든 텍스트 제거
        };

        // 툴팁 템플릿 (기존 동작하던 방식으로 수정)
        gantt.templates.tooltip_text = function (start, end, task) {
            var html = "";

            if (task.task_type === "planned") {
                html += "<div style='font-weight: bold; color: #007bff; margin-bottom: 8px;'>계획 일정</div>";
                html += "<div><b>업무명:</b> " + task.original_name + "</div>";
                html += "<div><b>단계:</b> " + (task.stage || "기타") + "</div>";
                html += "<div><b>상태:</b> " + (task.status || "대기") + "</div>";
                html += "<div><b>담당자:</b> " + (task.assignee || "미지정") + "</div>";
                html += "<div><b>진척률:</b> " + Math.round(task.progress * 100) + "%</div>";
                html += "<div style='margin-top: 8px;'>";
                html += "<div><b>계획 시작:</b> " + (task.planned_start || "미정") + "</div>";
                html += "<div><b>계획 완료:</b> " + (task.planned_end || "미정") + "</div>";
                html += "</div>";
                if (task.actual_start && task.actual_end) {
                    html += "<div style='margin-top: 8px; color: #6c757d;'>";
                    html += "실제 일정을 보려면 펼쳐주세요";
                    html += "</div>";
                }
            } else if (task.task_type === "actual") {
                html += "<div style='font-weight: bold; color: #ff9800; margin-bottom: 8px;'>실제 일정</div>";
                html += "<div><b>업무명:</b> " + task.original_name + "</div>";
                html += "<div><b>단계:</b> " + (task.stage || "기타") + "</div>";
                html += "<div><b>상태:</b> " + (task.status || "대기") + "</div>";
                html += "<div><b>담당자:</b> " + (task.assignee || "미지정") + "</div>";
                html += "<div><b>진척률:</b> " + Math.round(task.progress * 100) + "%</div>";
                html += "<div style='margin-top: 8px;'>";
                html += "<div><b>실제 시작:</b> " + (task.actual_start || "미정") + "</div>";
                html += "<div><b>실제 완료:</b> " + (task.actual_end || "미정") + "</div>";
                html += "</div>";

                // 계획 대비 실제 비교
                if (task.planned_start && task.actual_start) {
                    var plannedDate = new Date(task.planned_start);
                    var actualDate = new Date(task.actual_start);
                    var dayDiff = Math.floor((actualDate - plannedDate) / (1000 * 60 * 60 * 24));

                    html += "<div style='margin-top: 8px; padding: 4px; background: #f8f9fa; border-radius: 4px;'>";
                    if (dayDiff > 0) {
                        html += "<div style='color: #dc3545;'>계획보다 " + dayDiff + "일 늦음</div>";
                    } else if (dayDiff < 0) {
                        html += "<div style='color: #28a745;'>계획보다 " + Math.abs(dayDiff) + "일 빠름</div>";
                    } else {
                        html += "<div style='color: #17a2b8;'>계획대로 진행</div>";
                    }
                    html += "</div>";
                }
            }

            return html;
        };

        // 간트차트 초기화
        gantt.init("ganttCanvas");

        // 현재 날짜 마커 설정
        setTimeout(function () {
            var dateToStr = gantt.date.date_to_str(gantt.config.task_date);
            var today = new Date();
            gantt.addMarker({
                start_date: today,
                css: "today_marker",
                text: "오늘 (" + dateToStr(today) + ")",
                title: "현재 날짜: " + dateToStr(today)
            });
        }, 1000);

        console.log("DHTMLX Gantt 설정 초기화 완료 (계획/실제 트리 구조)");

    } catch (error) {
        console.error("Gantt 설정 초기화 오류:", error);
        scwin.showErrorState("간트차트 설정 초기화 실패: " + error.message);
    }
};

scwin.loadTaskList = function () {
    console.log("업무 목록 조회 요청");
    $c.sbm.execute($p, sbm_selectTaskList);
};

scwin.sbm_selectTaskList_submitdone = function (e) {
    try {
        console.log("서버 응답 수신:", e.responseJSON);
        var elData = e.responseJSON.elData;

        if (elData && elData.designVoList && elData.designVoList.length > 0) {
            console.log("업무 데이터 개수:", elData.designVoList.length);
            dlt_designVoList.setJSON(elData.designVoList);

            if (typeof gantt !== 'undefined') {
                scwin.createPlanActualGanttChart();
            } else {
                console.error("DHTMLX Gantt가 로드되지 않았습니다.");
                scwin.showErrorState("DHTMLX Gantt 라이브러리 로딩 실패");
            }
        } else {
            console.log("업무 데이터가 없음");
            scwin.showEmptyState();
        }
    } catch (error) {
        console.error("데이터 처리 오류:", error);
        scwin.showErrorState("데이터를 처리하는 중 오류가 발생했습니다.");
    }
};

/**
 * 계획(상위) - 실제(하위) 트리 구조 DHTMLX Gantt 차트 생성
 */
scwin.createPlanActualGanttChart = function () {
    try {
        var taskData = dlt_designVoList.getAllJSON();

        if (!taskData || taskData.length === 0) {
            scwin.showEmptyState();
            return;
        }

        // DHTMLX Gantt 데이터 형식으로 변환 (계획이 상위, 실제가 하위)
        var ganttData = {
            data: [],
            links: []
        };

        taskData.forEach(function (task, index) {
            var taskId = task.taskId || String(index + 1);
            var taskName = task.taskName || ("업무 " + (index + 1));
            var taskType = task.taskType || "기타";
            var taskStatus = task.taskStatus || "대기";
            var assignee = task.taskAsi || "미지정";
            var progress = parseFloat(task.taskRate || "0") / 100;

            // 1. 계획 일정 (상위 태스크)
            if (task.taskSt && task.taskEt) {
                var plannedTask = {
                    id: taskId + "_planned",
                    text: taskName + " (계획)",
                    start_date: task.taskSt,
                    end_date: task.taskEt,
                    duration: gantt.calculateDuration(new Date(task.taskSt), new Date(task.taskEt)),
                    progress: progress,
                    stage: taskType,
                    status: taskStatus,
                    assignee: assignee,
                    task_type: "planned",
                    original_name: taskName,
                    planned_start: task.taskSt,
                    planned_end: task.taskEt,
                    actual_start: task.taskRst,
                    actual_end: task.taskRet,
                    open: true // 기본적으로 펼쳐진 상태
                };
                ganttData.data.push(plannedTask);

                // 2. 실제 일정 (하위 태스크)
                if (task.taskRst && task.taskRet) {
                    var actualTask = {
                        id: taskId + "_actual",
                        text: taskName + " (실제)",
                        start_date: task.taskRst,
                        end_date: task.taskRet,
                        duration: gantt.calculateDuration(new Date(task.taskRst), new Date(task.taskRet)),
                        progress: progress,
                        stage: taskType,
                        status: taskStatus,
                        assignee: assignee,
                        task_type: "actual",
                        original_name: taskName,
                        parent: taskId + "_planned", // 계획 일정을 부모로 설정
                        planned_start: task.taskSt,
                        planned_end: task.taskEt,
                        actual_start: task.taskRst,
                        actual_end: task.taskRet
                    };
                    ganttData.data.push(actualTask);
                }
            } else if (task.taskRst && task.taskRet) {
                // 실제 일정만 있는 경우 (계획 없음)
                var actualOnlyTask = {
                    id: taskId + "_actual_only",
                    text: taskName + " (실제만)",
                    start_date: task.taskRst,
                    end_date: task.taskRet,
                    duration: gantt.calculateDuration(new Date(task.taskRst), new Date(task.taskRet)),
                    progress: progress,
                    stage: taskType,
                    status: taskStatus,
                    assignee: assignee,
                    task_type: "actual",
                    original_name: taskName,
                    planned_start: null,
                    planned_end: null,
                    actual_start: task.taskRst,
                    actual_end: task.taskRet,
                    open: true
                };
                ganttData.data.push(actualOnlyTask);
            }
        });

        // 간트차트에 데이터 파싱
        gantt.clearAll();
        gantt.parse(ganttData);

        console.log("DHTMLX Gantt 계획/실제 트리 구조 차트 생성 완료 - 업무 수:", taskData.length, "총 항목 수:", ganttData.data.length);

    } catch (error) {
        console.error("계획/실제 트리 구조 간트차트 생성 오류:", error);
        scwin.showErrorState("계획/실제 트리 구조 간트차트를 생성하는 중 오류가 발생했습니다: " + error.message);
    }
};

/**
 * 상태별 CSS 클래스 반환
 */
scwin.getStatusClass = function (status) {
    var classes = {
        '대기': 'status_waiting',
        '진행중': 'status_progress',
        '완료': 'status_completed',
        '지연': 'status_delayed',
        '보류': 'status_hold'
    };
    return classes[status] || 'status_waiting';
};

/**
 * 텍스트 자르기
 */
scwin.truncateText = function (text, maxLength) {
    if (!text) return '';
    return text.length > maxLength ? text.substring(0, maxLength) + '...' : text;
};

/**
 * 날짜 포맷팅
 */
scwin.formatDate = function (date) {
    try {
        if (typeof date === 'string') {
            return date;
        }
        return date.toLocaleDateString('ko-KR', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit'
        });
    } catch (e) {
        return date ? date.toString() : '';
    }
};

scwin.showEmptyState = function () {
    try {
        var chartWrapper = document.querySelector('.chart_canvas_wrapper');
        if (chartWrapper) {
            chartWrapper.innerHTML = '<div class="loading_state">표시할 업무가 없습니다</div>';
        }
    } catch (error) {
        console.error("빈 상태 표시 오류:", error);
    }
};

scwin.showErrorState = function (message) {
    try {
        var chartWrapper = document.querySelector('.chart_canvas_wrapper');
        if (chartWrapper) {
            chartWrapper.innerHTML = '<div class="error_state">' + message + '</div>';
        }
    } catch (error) {
        console.error("에러 상태 표시 오류:", error);
    }
};

// 버튼 이벤트
scwin.refreshData = function () {
    console.log("데이터 새로고침 요청");
    scwin.loadTaskList();
};

scwin.goToListPage = function () {
    console.log("리스트 페이지로 이동");
    $p.url("/InsWebApp/ui/task/design/DesignList.xml");
};

// 뷰 변경 함수들
scwin.changeToQuarterView = function () {
    try {
        gantt.config.scales = [
            {
                unit: "quarter",
                step: 1,
                format: function (date) {
                    var quarter = Math.floor(date.getMonth() / 3) + 1;
                    return date.getFullYear() + "년 " + quarter + "분기";
                }
            },
            { unit: "month", step: 1, format: "%m월" }
        ];
        gantt.config.min_column_width = 100;
        gantt.render();
        console.log("분기별 보기로 변경됨");
    } catch (error) {
        console.error("분기별 보기 변경 오류:", error);
    }
};

scwin.changeToMonthView = function () {
    try {
        gantt.config.scales = [
            { unit: "month", step: 1, format: "%Y년 %m월" },
            {
                unit: "week",
                step: 1,
                format: function (date) {
                    // 해당 월의 몇 번째 주인지 계산
                    var weekOfMonth = Math.floor((date.getDate() - 1) / 7) + 1;
                    return weekOfMonth + "주";
                }
            }
        ];
        gantt.config.min_column_width = 80;
        gantt.render();
        console.log("월별 보기로 변경됨");
    } catch (error) {
        console.error("월별 보기 변경 오류:", error);
    }
};

scwin.changeToDayView = function () {
    try {
        gantt.config.scales = [
            { unit: "month", step: 1, format: "%Y년 %m월" },
            { unit: "day", step: 1, format: "%d" }
        ];
        gantt.config.min_column_width = 30;
        gantt.render();
        console.log("일별 보기로 변경됨");
    } catch (error) {
        console.error("일별 보기 변경 오류:", error);
    }
};

// 전체 펼치기/접기 기능
scwin.expandAll = function () {
    try {
        gantt.eachTask(function (task) {
            if (gantt.hasChild(task.id)) {
                gantt.open(task.id);
            }
        });
        console.log("모든 항목 펼치기 완료");
    } catch (error) {
        console.error("전체 펼치기 오류:", error);
    }
};

scwin.collapseAll = function () {
    try {
        gantt.eachTask(function (task) {
            if (gantt.hasChild(task.id)) {
                gantt.close(task.id);
            }
        });
        console.log("모든 항목 접기 완료");
    } catch (error) {
        console.error("전체 접기 오류:", error);
    }
};
